import {useEffect} from 'react'
import {PageHeader} from '@primer/react'
import {useRouteQuery} from '@github-ui/react-core/future/use-route-query'
import type {CustomImageListPagePayload} from '../types/payloads'
import {customImages} from '../helpers/constants'
import {customImagesRoute} from './custom-images-list-route'
import {CustomImagesView} from '../components/CustomImagesView'
import {customImagesEnterpriseRoute} from './custom-images-list-enterprise-route'

export function CustomImageListPageEntrypointForOrg() {
  const {data: payload} = useRouteQuery(customImagesRoute, 'mainQuery')
  return <CustomImageListPage payload={payload} />
}

export function CustomImageListPageEntrypointForEnterprise() {
  const {data: payload} = useRouteQuery(customImagesEnterpriseRoute, 'mainQuery')
  return <CustomImageListPage payload={payload} />
}

function CustomImageListPage({payload}: {payload: CustomImageListPagePayload}) {
  useEffect(() => {
    window.scrollTo(0, 0)
  }, [])

  return (
    <>
      <PageHeader>
        <PageHeader.TitleArea>
          <PageHeader.Title as="h1">{customImages.PageTitle}</PageHeader.Title>
        </PageHeader.TitleArea>
      </PageHeader>
      <CustomImagesView
        images={payload.imageDefinitions}
        baseUrl={payload.baseUrl}
        ownerId={payload.ownerId}
        retentionPolicies={payload.retentionPolicies}
      />
    </>
  )
}

try{ CustomImageListPageEntrypointForOrg.displayName ||= 'CustomImageListPageEntrypointForOrg' } catch {}
try{ CustomImageListPageEntrypointForEnterprise.displayName ||= 'CustomImageListPageEntrypointForEnterprise' } catch {}
try{ CustomImageListPage.displayName ||= 'CustomImageListPage' } catch {}