import {Table} from '@primer/react/experimental'
import type {ImageDefinition} from '../types/types'
import {CustomImagesTable} from './CustomImagesTable'
import {CustomImagesViewSummary} from './CustomImagesViewSummary'

import styles from '../styles/components/TableContainer.module.css'
import type {RetentionPolicies} from '../types/payloads'

interface CustomImagesViewProps {
  images: ImageDefinition[]
  baseUrl: string
  ownerId: string
  retentionPolicies: RetentionPolicies
}

export function CustomImagesView(props: CustomImagesViewProps) {
  const customImagesCount = props.images.length

  return (
    <div className={styles.tableContainer}>
      <div>
        <CustomImagesViewSummary
          customImages={props.images}
          ownerId={props.ownerId}
          retentionPolicies={props.retentionPolicies}
        />
        <Table.Container>
          <Table.Title as="h2" id="curated-images">
            Images ({customImagesCount})
          </Table.Title>
          {customImagesCount > 0 && <CustomImagesTable images={props.images} baseUrl={props.baseUrl} />}
        </Table.Container>
      </div>
    </div>
  )
}

try{ CustomImagesView.displayName ||= 'CustomImagesView' } catch {}